import copy
import unittest
from report import enabled_names, enabled_total

class AccessRow(dict):
    def __init__(self, values):
        super().__init__(values)
        self.reads = []
    def __getitem__(self, key):
        self.reads.append(key)
        return super().__getitem__(key)

class OnePass:
    def __init__(self, rows, field):
        self.rows, self.field, self.started = rows, field, False
    def __iter__(self):
        assert not self.started, 'input iterated twice'
        self.started = True
        for row in self.rows:
            yield row
            expected = ['enabled', self.field] if dict.__getitem__(row, 'enabled') is True else ['enabled']
            assert row.reads == expected, ('row must be processed once before next input', row.reads, expected)

class RefactorContract(unittest.TestCase):
    def test_order_duplicates_and_types(self):
        rows = [{'enabled': True, 'name': 'z', 'amount': 3},
                {'enabled': True, 'name': 'a', 'amount': -5},
                {'enabled': True, 'name': 'z', 'amount': 2}]
        names = enabled_names(iter(rows))
        self.assertIs(type(names), list)
        self.assertEqual(names, ['z', 'a', 'z'])
        result = enabled_total(iter(rows))
        self.assertIs(type(result), int)
        self.assertEqual(result, 0)
        self.assertIs(type(enabled_total(iter([]))), int)
        self.assertEqual(enabled_names(iter([])), [])

    def test_strict_true(self):
        rows = [{'enabled': value, 'name': str(i), 'amount': 2}
                for i, value in enumerate([1, 'yes', [], False, None, True])]
        self.assertEqual(enabled_names(iter(rows)), ['5'])
        self.assertEqual(enabled_total(iter(rows)), 2)

    def test_preserves_name_objects_and_numeric_types(self):
        from decimal import Decimal
        name = object()
        self.assertIs(enabled_names([{'enabled': True, 'name': name}])[0], name)
        result = enabled_total([{'enabled': True, 'amount': Decimal('1.25')}])
        self.assertIs(type(result), Decimal)
        self.assertEqual(result, Decimal('1.25'))

    def test_errors_and_field_independence(self):
        for function, field in ((enabled_names, 'name'), (enabled_total, 'amount')):
            for row, missing in (({}, 'enabled'), ({'enabled': True}, field)):
                with self.subTest(function=function.__name__, missing=missing):
                    with self.assertRaises(KeyError) as error:
                        function(iter([row]))
                    self.assertEqual(error.exception.args, (missing,))
        self.assertEqual(enabled_names([{'enabled': False}]), [])
        self.assertEqual(enabled_total([{'enabled': False}]), 0)
        self.assertEqual(enabled_names([{'enabled': True, 'name': 'x'}]), ['x'])
        self.assertEqual(enabled_total([{'enabled': True, 'amount': 4}]), 4)

    def test_no_input_mutation(self):
        for function in (enabled_names, enabled_total):
            rows = [{'enabled': True, 'name': 'b', 'amount': 3},
                    {'enabled': False, 'name': 'a', 'amount': 4}]
            before = copy.deepcopy(rows)
            function(rows)
            self.assertEqual(rows, before)

    def test_single_pass_streaming_and_linear_access(self):
        for function, field in ((enabled_names, 'name'), (enabled_total, 'amount')):
            for size in (0, 1, 64, 257):
                with self.subTest(function=function.__name__, size=size):
                    rows = [AccessRow({'enabled': i % 3 == 0, 'name': str(i), 'amount': i})
                            for i in range(size)]
                    actual = function(OnePass(rows, field))
                    expected = ([str(i) for i in range(size) if i % 3 == 0]
                                if field == 'name' else sum(i for i in range(size) if i % 3 == 0))
                    self.assertEqual(actual, expected)
                    self.assertEqual(sum(row.reads.count('enabled') for row in rows), size)
                    self.assertEqual(sum(row.reads.count(field) for row in rows), len(range(0, size, 3)))

if __name__ == '__main__':
    unittest.main()

